// Written operational reviews and design tasks. Commands are reference answers
// for disposable fixtures, not actions executed by the Practice workspace.
const review=(topic,difficulty,slug,title,prompt,objective,requirements,cases,hints,answer,followUp)=>({
    id:`backend-deploy-${slug}-v1`,career:'Backend Developer',phase:'Deployment & System Design',topic,title,difficulty,
    kind:'written',language:'Engineering reference',estimatedTime:difficulty==='Easy'?'20–30 minutes':difficulty==='Medium'?'35–50 minutes':'50–75 minutes',
    problemStatement:prompt,simplerProblem:objective,learningObjectives:[objective,`Verify the ${topic} boundary scenario before accepting the proposed design.`],
    prerequisites:['Node.js request lifecycle','Basic data ownership and failure handling'],conceptsToReview:[topic],requirements,
    examples:cases.map(([input,output])=>({input,output,explanation:objective})),tests:cases.map(([input,expected],i)=>({name:`Acceptance scenario ${i+1}`,input,expected})),
    hints,approach:`${hints[0]} ${hints[1]} Use the stated workload and failure evidence to evaluate the control rather than assuming a tool name proves correctness.`,
    walkthrough:cases.map(([input,output])=>`${input} → ${output}`).join('\n'),solutionCode:answer,solutionLines:answer.split('\n').filter(Boolean),
    completionCriteria:requirements,commonMistakes:[],starterCode:'Observed evidence and assumptions:\n\nCommand or design:\n\nAcceptance checks and failure behavior:\n',followUp
});

export const BACKEND_DEPLOYMENT_PRACTICE=[
    review('Linux','Easy','linux-file-paths','Inspect paths containing spaces without changing files',
        'A Linux support bundle contains a directory named support logs and a file named api error.log. Describe commands to print the current directory, list hidden entries, and display the final 20 lines of that file without treating spaces as argument separators or modifying the bundle.',
        'Use quoted path arguments and read-only inspection commands.',
        ['Quote the complete path and use -- before path operands where supported.','Do not use destructive cleanup commands during inspection.'],
        [['File support logs/api error.log exists','tail prints its final 20 lines.'],['Directory name begins with a hyphen','Use an explicit relative path or option terminator so it is not parsed as an option.']],
        ['Shell tokenization happens before the utility receives arguments.','Single quotes preserve literal spaces without command substitution.'],
        "pwd\nls -la -- 'support logs'\ntail -n 20 -- 'support logs/api error.log'\nEach quoted path is one argument. Run from the bundle parent or use its verified absolute path. A missing/unreadable file is an error to investigate, not a reason to change permissions broadly. Avoid exposing secrets from logs when sharing the resulting evidence.",
        'Explain how to inspect a literal filename containing a newline safely.'),
    review('Linux','Easy','linux-mode','Set an application secret file to owner-only access',
        'A Linux secret file owned by the service account currently has mode 0644. The service needs read/write access and no other user or group should read it. Specify the intended mode and verification, noting that directory traversal permissions and ACLs can affect effective access.',
        'Interpret file mode bits without recommending world-writable permissions.',
        ['Set mode 0600 on the verified fixture file.','Verify ownership, parent directories, and any ACL policy before claiming effective isolation.'],
        [['Owner accesses a regular fixture secret after chmod','Owner can read/write; mode grants no group/other access.'],['Process runs as a different account','Mode 0600 does not grant that account access; investigate identity rather than using 0777.']],
        ['The three octal groups represent owner, group, and other permissions.','File access also depends on the process identity and traversable parents.'],
        "chmod 600 -- 'app-secret'\nstat -c '%a %U %G' -- 'app-secret'\nFor this regular file, 6 means owner read plus write, and both remaining groups are zero. Verify the service actually runs as the owner, inspect parent directory permissions, ACLs, and security-module denials where applicable. Do not expose the secret through logs or backups with broader permissions.",
        'Compare a read-only secret mount for a service that never needs to update the file.'),
    review('Linux','Easy','linux-process','Identify the listening process before stopping anything',
        'A Linux API cannot bind port 3000 because another process is listening. Propose a read-only investigation that associates the listener with its process and service manager, without killing an arbitrary PID or assuming every listener is an abandoned development server.',
        'Connect socket evidence with process ownership before intervention.',
        ['Inspect the listening socket and its process with appropriate visibility.','Check command, owner, and service ownership before proposing a stop.'],
        [['ss shows PID 412 listening on TCP 3000','Inspect PID 412 rather than guessing from a process-name substring.'],['Listener belongs to a managed production service','Use its service lifecycle and authorization process, not an unreviewed kill.']],
        ['A port conflict is an ownership question before it is a cleanup task.','Process detail visibility can require additional authorized privileges.'],
        "ss -ltnp 'sport = :3000'\nps -p 412 -o pid,ppid,user,args\nUse the actual observed PID instead of blindly copying 412. Inspect the relevant service unit/status if managed. Lack of process details may be a visibility permission limit; do not escalate or stop a service without appropriate authority. Decide whether to reuse a dev process, choose another port, or stop an owned fixture through its manager.",
        'Explain how a container port mapping changes where to inspect the listener.'),
    review('Linux','Medium','linux-disk','Distinguish full blocks, full inodes, and deleted-open files',
        'A Linux application reports no space left on device while a directory summary appears small. Design an investigation covering filesystem capacity, inode exhaustion, and a deleted file still held open, without deleting unknown data or restarting every process immediately.',
        'Use filesystem and process evidence to explain storage exhaustion.',
        ['Compare df block and inode reports for the actual mount.','Investigate open deleted files and retention ownership before reclaiming space.'],
        [['df shows blocks available but df -i is exhausted','Many small files may be the limiting resource.'],['Deleted log remains open by the API','Space may remain allocated until the owning descriptor is closed.']],
        ['du reports visible directory entries, while df reports filesystem allocation.','Use mount boundaries and read-only process inspection to avoid blaming another filesystem.'],
        "df -h -- /var/lib/app\ndf -i -- /var/lib/app\ndu -x -h --max-depth=1 -- /var/lib/app\nInspect deleted-open files with an authorized tool such as lsof +L1 and correlate the owning PID. Confirm log/data retention policy before cleanup. For an owned service, prefer a supported log-reopen/rotation mechanism or a planned restart when needed; unlinking more files does not necessarily release an open allocation. Also consider filesystem snapshots/reserved space when totals differ.",
        'Define a safe alert threshold for both inode and block exhaustion.'),
    review('Linux','Medium','linux-signal','Stop a worker gracefully before considering SIGKILL',
        'A Linux queue worker is being upgraded while it owns a job. Compare SIGTERM and SIGKILL, and define a supervised shutdown that stops new claims, drains or safely abandons current work, and has a bounded deadline.',
        'Coordinate process signals with job ownership and recovery.',
        ['Handle SIGTERM with idempotent stop-admission and cleanup logic.','Use a deadline and lease/idempotency policy rather than assuming abrupt termination rolls back external effects.'],
        [['Worker finishes before the deadline','Acknowledge confirmed work, close owned resources, and exit.'],['Worker is forcibly terminated mid-job','A lease/redelivery policy recovers work without claiming the prior effect did not occur.']],
        ['SIGKILL cannot run application cleanup handlers.','The service manager and queue visibility window must agree with the drain budget.'],
        'On SIGTERM mark the worker draining, stop fetching new jobs, and wait for current owned work under a deadline. Complete/ack only confirmed outcomes and close resources after work settles.\nIf the deadline requires forced termination, record the uncertainty and rely on lease expiry plus idempotent processing for recovery. Do not kill unknown processes, and use the service manager to avoid immediate unintended respawns. Test repeated signals and a never-finishing job; container PID 1 forwarding must also be verified.',
        'Specify the termination grace period relative to a queue visibility extension.'),
    review('Linux','Medium','linux-logs','Correlate service failures without dumping secrets',
        'A Linux service intermittently fails after deployment. Design a read-only incident timeline using service status and journal entries, correlate request IDs with the deployment version, and distinguish a permission failure from a missing configuration file.',
        'Gather bounded operational evidence before changing service state.',
        ['Inspect the correct unit, time interval, exit status, and process identity.','Redact credentials and preserve useful error codes and timestamps.'],
        [['Journal shows EACCES for the service account','Inspect ownership, directory access, and confinement policy.'],['Journal shows ENOENT for a relative configuration path','Inspect WorkingDirectory and configured path rather than making every file readable.']],
        ['A bounded journal query is easier to correlate than an unlimited log dump.','Relative paths depend on the service working directory, not the interactive shell.'],
        "systemctl status --no-pager api.service\njournalctl -u api.service --since '2026-01-01 10:00:00 UTC' --until '2026-01-01 10:10:00 UTC' --no-pager\nReplace the example unit/time window with the incident evidence. Inspect User/WorkingDirectory and the relevant file metadata without printing secret contents. Correlate release IDs and request IDs, then propose a targeted fix. Journals may require authorized access and have separate retention/redaction controls.",
        'Design a rollback trigger based on failure-rate evidence rather than a single expected warning.'),
    review('Linux','Hard','linux-resource-limits','Diagnose a stalled service with memory and descriptor evidence',
        'A Linux API stops accepting requests although average CPU is low. Logs show occasional EMFILE and the process is near its memory limit. Design an investigation separating descriptor leaks, connection accumulation, and memory pressure; do not merely raise all limits.',
        'Trace resource growth to an owned lifecycle and bounded capacity.',
        ['Measure descriptors, connections, RSS/cgroup memory, and request concurrency over time.','Fix leak/admission behavior before treating higher limits as the complete solution.'],
        [['Descriptor count grows after each failed request','Inspect missing close/finally paths and connection cleanup.'],['Memory approaches a cgroup limit while host memory looks free','Container/service resource limits still constrain the process.']],
        ['Host-wide averages can hide a per-process or cgroup limit.','A reproducible load and failure path helps distinguish retained state from a temporary burst.'],
        'Inspect /proc/<pid>/fd counts and types, socket state, process limits, and the relevant service/cgroup memory metrics under authorized read access. Correlate growth with success/failure paths and a bounded load test.\nClose owned handles on every path, cap in-flight/queued work, bound pools, and investigate retained buffers with appropriate profiling. Increasing limits can buy headroom but may enlarge the failure blast radius or exceed downstream capacity. Define acceptance as stable resource use after repeated normal/error cycles, not one successful request after restart.',
        'Specify an experiment that distinguishes a connection leak from a deliberately bounded pool.'),
    review('Linux','Hard','linux-atomic-config','Publish a complete configuration without exposing a partial write',
        'A Linux service reloads a configuration file while another process rewrites it in place. Readers see truncated JSON. Design a same-directory temporary-file replacement and explicit reload confirmation, distinguishing atomic visibility from crash durability and semantic validity.',
        'Publish a validated version through a controlled filesystem and process boundary.',
        ['Validate configuration before replacement and preserve a known-good version.','Use a same-filesystem replacement under verified platform semantics and acknowledge successful reload separately.'],
        [['Writer fails while preparing the temporary file','Live configuration remains the previous complete version.'],['New file is published but service rejects its semantics','Do not claim a successful rollout; restore/reload the known-good version through the documented procedure.']],
        ['Rename avoids exposing an in-place partial file under the stated filesystem assumptions.','A complete file may still be invalid for the application.'],
        'Write a unique restrictive temporary file in the target directory, validate schema/semantics, close/sync as required, and rename over the live path using supported replacement semantics. For crash durability assess file and directory synchronization on the actual filesystem.\nRequest a supported reload and verify the loaded config version plus readiness; preserve the last known-good configuration for controlled recovery. Use one authorized writer or version checks for concurrent updates. Do not assume every network filesystem or process automatically observes the same rename/reload behavior.',
        'Define how symlink attacks are prevented in an attacker-writable configuration directory.'),
    review('Linux','Hard','linux-sandbox','Reduce service privileges without breaking required writes',
        'A Linux API runs as root with broad filesystem access but needs only to bind an unprivileged port and write a cache directory. Design a systemd-style least-privilege service boundary with a read-only application tree and explicit writable paths, including verification and rollback.',
        'Map service capabilities to a narrow tested operating-system policy.',
        ['Use a dedicated unprivileged account and allow only required writable state.','Test confinement in a fixture/staging service before rollout and keep secrets outside the image/tree.'],
        [['API tries to modify its executable files','The policy denies the write.'],['API writes to its approved cache directory','It succeeds with correct ownership while unrelated filesystem paths remain protected.']],
        ['Root convenience hides the difference between needed and accidental permissions.','Sandbox options depend on runtime, filesystem, and service-manager support.'],
        'Run under a dedicated User/Group, use an unprivileged listener behind the ingress, and define owned state directories. Evaluate controls such as NoNewPrivileges, ProtectSystem, and explicit writable paths plus a minimal capability set according to the supported systemd version.\nTest startup, read-only code, approved writes, DNS/network needs, temporary files, signals, and diagnostics. Monitor policy denials and roll back through the service manager if legitimate operations fail; do not broadly chmod 777 or disable the entire boundary without evidence. This is a deployment design, not an instruction to alter the current machine.',
        'Specify how a secret rotation can occur without granting the service write access to its own credentials.'),

    review('Docker','Easy','docker-image-container','Separate an immutable image from a running instance',
        'A Docker beginner edits a file inside one running API container and expects new replicas to contain the edit. Explain image versus container writable state and design a reproducible change through a rebuilt tagged/digested artifact rather than patching each live instance.',
        'Treat a container as an instance of a reviewed image artifact.',
        ['Put application changes into source/build inputs and rebuild the image.','Identify deployments by an immutable digest rather than relying only on a mutable tag.'],
        [['One running container is edited','Sibling/new containers do not automatically inherit that writable-layer change.'],['New image is built and deployed by digest','Every replica can use the same reviewed artifact.']],
        ['A container writable layer is not an update to the source image.','Tags can move; a digest names image content.'],
        'Commit/review the intended source change, rebuild with controlled inputs, run image tests, and deploy the resulting immutable digest. Keep the old digest for rollback.\nDo not use hand-edited container files as the release source of truth. Mount intended runtime configuration or managed persistent data separately, and keep secrets out of image layers. Recreating a container should recover the intended code from the artifact rather than requiring undocumented manual repairs.',
        'Explain how configuration differs from an application binary release.'),
    review('Docker','Easy','docker-port','Map a local fixture port and bind the application correctly',
        'A Docker API listens on 127.0.0.1:3000 inside its container. Publishing host port 8080 still gives connection failures. Explain network namespaces and provide a safe local-fixture mapping while avoiding unnecessary exposure on every host interface.',
        'Distinguish container bind address, container port, and host publication.',
        ['Bind the API to 0.0.0.0:3000 inside the container when external container traffic is intended.','For a local-only fixture publish 127.0.0.1:8080:3000.'],
        [['API binds only container loopback','Host publication cannot make it listen on the container network interface.'],['API binds container interfaces and local-only mapping is configured','Host localhost:8080 reaches the intended container port.']],
        ['Loopback refers to the current network namespace.','EXPOSE documents a port but does not itself publish it to the host.'],
        'Configure the fixture API listener for host 0.0.0.0 and port 3000, then run the reviewed image with docker run --rm -p 127.0.0.1:8080:3000 <verified-image>. Replace the notation with a verified artifact rather than an arbitrary image.\nThe host-side 127.0.0.1 limits local fixture exposure; production networking requires its own ingress/firewall policy. Check application logs and listening state before changing mappings. EXPOSE alone is not host port publication and localhost inside the container is not the host loopback.',
        'Describe access between two containers on a user-defined network without publishing the database port.'),
    review('Docker','Easy','docker-volume','Preserve intended data across container replacement',
        'A Docker fixture writes uploaded files into the container writable layer. Replacing the container loses access to those files. Choose a named volume for a single-host fixture, distinguish its lifecycle from the container, and explain why it is not a backup or a multi-host storage design.',
        'Separate persistent data ownership from disposable process instances.',
        ['Mount a named volume at the application’s documented data path.','Do not delete/prune volumes as routine rollback and plan tested backups separately.'],
        [['Fixture container is removed and replaced using the same named volume','Its intended data remains available.'],['Host disk fails','A named local volume alone does not provide an independent recovery copy.']],
        ['Container deletion and named-volume deletion are different operations.','Mounting over a path can hide files already present in the image.'],
        'Use a controlled fixture volume such as api-fixture-data mounted at /app/data, with the service UID able to access it. Recreate the container using the same mount and verify a known fixture file.\nDo not interpret persistence as replication or backup. Define ownership, backup/restore testing, retention, and secure cleanup for the actual data. For multiple hosts choose storage suited to access and consistency requirements rather than assuming a local Docker volume follows every replica.',
        'Design an explicit restore drill using disposable files only.'),
    review('Docker','Medium','docker-multi-stage','Keep build tooling out of a Node runtime image',
        'A Docker TypeScript API ships compiler tools, source fixtures, and development dependencies in production. Design a multi-stage build producing dist and runtime dependencies from the lockfile, keeping the runtime compatible with any native modules.',
        'Separate build-time inputs from runtime artifacts.',
        ['Build and test before producing the runtime stage.','Copy only required output/runtime dependencies and run under a non-root identity.'],
        [['Compiler is needed only to produce dist','It belongs to the build stage.'],['Native dependency compiled for a different libc/architecture','Do not assume copied node_modules will run; match the target environment.']],
        ['Stages can use independent dependency installations.','Use compatible bases and a committed lockfile.'],
        'Use a reviewed Node base in a build stage: copy manifest/lock, npm ci, copy source, test, and compile. In a compatible runtime stage install npm ci --omit=dev from the same lockfile and copy dist plus required assets.\nSet ownership and USER to an unprivileged account; use exec-form startup. Pin/review base updates and exclude secrets with a narrow build context. Test the final image, including native modules and runtime assets, rather than only the builder.',
        'Specify how a generated database client becomes part of the final tested artifact.'),
    review('Docker','Medium','docker-layer-cache','Order dependency layers without caching stale dependencies',
        'A Docker build copies the entire repository before npm ci, so editing a README reinstalls dependencies. Reorder inputs for cache reuse, preserve lockfile integrity, and exclude host node_modules without implying that build cache replaces dependency verification.',
        'Cache dependency work according to its actual inputs.',
        ['Copy package manifests and lockfile before installing.','Use .dockerignore for host dependencies, secrets, and irrelevant artifacts.'],
        [['Only application source changes','The dependency-install layer can be reused when its inputs are unchanged.'],['Lockfile changes','The dependency layer must be rebuilt under npm ci.']],
        ['A cache key depends on earlier layer inputs.','Host modules can be incompatible and must not overwrite image-installed dependencies.'],
        'Set WORKDIR, copy package.json/package-lock.json, run npm ci, then copy the needed source and build. Provide a .dockerignore excluding node_modules, credentials, and unnecessary outputs.\nFor workspaces include all manifest/lock/config inputs that affect resolution before install. Use controlled base-image refresh and cache invalidation policy for security updates; a cached layer is not proof dependencies are current or trustworthy. Verify the final dependency graph and artifact in CI.',
        'Explain when an npm configuration change should invalidate the dependency layer.'),
    review('Docker','Medium','docker-service-network','Connect API and database through scoped service networking',
        'A Docker Compose API tries localhost:5432 and fails because PostgreSQL runs in another container. Design service-name resolution on a user-defined network, limited database exposure, and startup behavior when the database is not yet ready.',
        'Use service identity and readiness rather than namespace-local assumptions.',
        ['Use the database service name and container port for API connections.','Retry bounded connection startup and avoid publishing the database unnecessarily.'],
        [['API connects to db:5432 on the shared network','It reaches the database service under network policy.'],['Database container exists but is still initializing','API waits/retries under a bounded readiness policy, not immediate success.']],
        ['localhost means the API container itself.','Startup order alone does not prove dependency readiness.'],
        'Place API and database on an explicitly scoped network; configure the API host as the database service name, for example db, not localhost. Keep credentials in runtime secret configuration and database access least-privileged.\nDo not publish the DB port unless a deliberate host-access use case requires it. Use readiness checks plus bounded retry/backoff for initialization and reconnects. Test database restart and network failure as well as initial startup; a dependency declaration is not a permanent availability guarantee.',
        'Define how the API reports readiness during a database outage.'),
    review('Docker','Hard','docker-build-secrets','Keep registry credentials out of image layers',
        'A Docker build uses ARG for a private package token and later deletes an .npmrc file. Explain why deletion in a later layer is insufficient and design a build-secret mechanism with constrained CI identity and artifact inspection.',
        'Separate temporary build authorization from distributable image content.',
        ['Use an approved BuildKit secret mount rather than ARG/ENV for credentials.','Check logs, layers, and generated artifacts for leakage and rotate any exposed token.'],
        [['Token is copied then deleted in a later layer','Earlier layers may still contain it.'],['Secret is mounted only for the dependency operation','It is not automatically copied into the resulting layer, though commands can still leak it.']],
        ['Image layers and build logs outlive a shell command.','A secret mount does not stop malicious build code from reading or exfiltrating the secret.'],
        'Supply a short-lived narrowly scoped registry credential through a CI-approved secret channel and use a BuildKit secret mount only for the install operation. Do not print or copy it into output, caches, lock metadata, or runtime ENV.\nInspect the packed image/history and logs, and isolate untrusted install scripts from deployment credentials. Masking is not a guarantee against transformed secrets. Revoke exposed credentials and rebuild clean artifacts; deleting a leaked file in a later layer is not remediation of already shared layers.',
        'Design a safe rehearsal using a dummy canary token instead of a real credential.'),
    review('Docker','Hard','docker-signal-drain','Test signal delivery and shutdown in the final image',
        'A Docker API starts through a shell wrapper that does not exec the Node process. During deployment the container fails to drain before termination. Design process ownership, signal forwarding, and bounded HTTP shutdown, including persistent connections.',
        'Align container process lifecycle with application cleanup.',
        ['Use exec-form CMD or a wrapper ending in exec and appropriate init handling.','Stop admission and drain active work within the orchestrator grace period.'],
        [['Container receives SIGTERM','The API receives it and begins idempotent shutdown.'],['An upgraded connection never drains','The deadline invokes a documented forced-close path rather than waiting forever.']],
        ['The container’s PID 1 has special process/signal responsibilities.','The grace period must exceed the intended normal drain budget.'],
        'Use exec-form startup such as CMD ["node","dist/server.js"] and an appropriate minimal init when child reaping is required. The API handles SIGTERM by failing readiness, stopping admission, draining requests, then closing dependencies.\nTrack upgraded connections separately and enforce a deadline shorter than forced container termination. Test the actual image under ordinary requests, long-lived connections, repeated signals, and an in-flight write. Forced termination does not roll back external effects, so retries still need idempotency.',
        'Define acceptance evidence for a rolling shutdown that does not drop normal short requests.'),
    review('Docker','Hard','docker-mutable-tags','Promote one verified digest across environments',
        'A Docker release tags each fresh environment build as latest. Staging passes, but production rebuilds different dependencies. Design immutable artifact promotion with provenance, vulnerability review, rollback identity, and environment-specific configuration.',
        'Deploy the tested artifact rather than rebuilding an approximation.',
        ['Build once and record digest, source revision, dependency graph, and checks.','Promote that digest and inject runtime configuration separately.'],
        [['Staging and production claim the same release','Verify the deployed digest is identical, not only the tag label.'],['Rollback is needed','Deploy the previous verified digest subject to schema compatibility.']],
        ['A mutable tag is a reference, not immutable content identity.','Runtime secrets/config should not require embedding a new artifact per environment.'],
        'Build a controlled artifact once, test the final image, record its digest and provenance, and promote by digest through deployment gates. Review signatures/provenance under an established trust policy and scan dependencies with a defined remediation process.\nKeep environment configuration and secrets external, verify architecture/platform variants, and record the actual deployed identity. Retain known-good artifacts and confirm database compatibility before rollback. A digest proves content identity, not that the content is safe or correctly authorized.',
        'Specify how a critical base-image fix produces a new reviewed release rather than silently moving latest.'),

    review('CI/CD','Easy','ci-failing-gate','Block packaging when a test fails',
        'A CI/CD script runs tests and then always builds/deploys because its shell sequence ignores the test exit status. Design a command-level gate and a pipeline dependency graph that stops promotion when tests fail.',
        'Make failure propagation part of the release contract.',
        ['Use fail-fast command chaining and checked job dependencies.','Do not mark required tests as continue-on-error or append unconditional success.'],
        [['Tests return nonzero','Packaging/deployment does not run under the required gate.'],['Tests and build succeed','A reviewed later promotion job may consume the resulting artifact.']],
        ['A command being present in a workflow does not make its result required.','Job dependencies must reflect the same intended ordering as shell commands.'],
        'npm ci && npm test && npm run build\nRun this only for a project whose test/build scripts are meaningful, and propagate its failure to CI. In the pipeline make artifact publication depend on the required check job; protect the release path from bypasses. Avoid shell patterns that overwrite a failure status or unconditional deploy steps. A passing build alone does not prove tests ran.',
        'Add a deliberate failing test fixture to verify the gate itself.'),
    review('CI/CD','Easy','ci-lockfile','Use a committed dependency graph in clean CI',
        'A CI/CD runner uses npm install without a committed lockfile while developers use different dependency versions. Design a clean-install workflow and explain how manifest/lockfile drift should fail rather than being silently resolved during deployment.',
        'Make dependency installation reproducible enough to review.',
        ['Commit the intended lockfile and use npm ci with consistent project configuration.','Review dependency updates separately and pin the supported runtime/toolchain policy.'],
        [['Manifest disagrees with lockfile','CI fails instead of rewriting dependencies during release.'],['Fresh runner installs a matching lockfile','It uses the locked graph under the chosen toolchain and flags.']],
        ['The lockfile is part of the build input.','Reproducibility also depends on runtime, registry, scripts, and platform.'],
        'Commit manifest and lockfile changes together, configure the supported Node/npm environment, and run npm ci before tests/build. Keep dependency-shaping flags consistent with lockfile creation.\nTreat installation script execution as trusted code with bounded privileges; do not give ordinary dependency-install jobs production credentials. Record provenance and review resolved changes. A lockfile improves graph identity but does not prove package code is safe or every build byte is deterministic.',
        'Specify how workspace manifests participate in the clean-install inputs.'),
    review('CI/CD','Easy','ci-secret-log','Remove credentials from workflow commands and logs',
        'A CI/CD deployment step prints its environment for debugging, exposing a registry token. Design credential delivery and incident handling without assuming automatic log masking catches every transformed secret.',
        'Minimize pipeline secret exposure and revoke confirmed leaks.',
        ['Use scoped secret delivery and avoid dumping environment/command expansions.','Revoke or rotate the leaked credential and review artifact/log exposure.'],
        [['A token appears in a shared build log','Treat it as exposed; masking it later does not revoke copies.'],['A test-only job runs','It receives no production deployment credentials.']],
        ['Logs are another durable access surface.','Secret availability should follow the job’s actual privilege needs.'],
        'Deliver narrowly scoped short-lived credentials only to the required protected job through the platform’s secret/federated-identity mechanism. Remove environment dumps and avoid echoing or transforming tokens into log-visible strings.\nRevoke leaked credentials, restrict/remove exposed logs under policy, and inspect artifacts/caches for copies. Test redaction with dummy secrets. Do not rely on masking as the only barrier or put secret values directly into repository YAML.',
        'Design separate permissions for reading packages and publishing a release.'),
    review('CI/CD','Medium','ci-artifact','Test and deploy the same packaged output',
        'A CI/CD test job runs source tests, while a later deployment job rebuilds from a floating branch. Design artifact identity, integrity verification, and a smoke test of the packaged runtime so the checked result corresponds to what is promoted.',
        'Connect source checks to a specific deployable artifact.',
        ['Build from an immutable revision and record the artifact digest.','Run package/runtime checks and promote that exact artifact without rebuilding from a moving branch.'],
        [['Branch advances after the test job','The pending release still refers to the original verified artifact or is superseded explicitly.'],['Artifact transfer is corrupted','Integrity verification fails before deployment.']],
        ['Source revision and artifact identity both matter.','A compiled output can omit runtime assets even when source tests pass.'],
        'Checkout an immutable revision, install the reviewed graph, run checks, build/package once, then smoke-test that package in its runtime environment. Publish immutable digest/provenance metadata and verify it when downloading for promotion.\nMake environment deployment consume the tested identity, not a fresh build from a branch. Protect artifact publication and approval boundaries and retain known-good versions. Record the release/config pair actually deployed; do not confuse the artifact hash with runtime configuration identity.',
        'Add a check for a required template file missing from the package.'),
    review('CI/CD','Medium','ci-schema-rollback','Plan a rollout that remains compatible with rollback',
        'A CI/CD release renames a required database column and immediately removes the old one. The new API fails and the old binary cannot run against the changed schema. Design an expand-and-contract rollout with compatibility gates and a rollback boundary.',
        'Coordinate application and schema changes across mixed-version deployments.',
        ['Expand compatibly before cutting reads/writes over.','Delay destructive contraction until old versions and rollback requirements are retired.'],
        [['New and old replicas overlap during rollout','Both can read/write under the transitional contract.'],['New version is rolled back before contraction','The previous artifact still works with the expanded schema.']],
        ['Rolling deployment means more than one writer version may be active.','An application rollback cannot automatically reverse every data migration.'],
        'Add compatible fields/indexes first, deploy transitional readers/writers, backfill with checkpoints and concurrency protection, and verify consistency before switching the canonical path.\nRetain legacy compatibility through the support/rollback window, then contract in a separately reviewed release. Test rollback against the migrated schema using disposable data. If a destructive migration has crossed the boundary, a forward fix or tested restore may be required; do not promise a binary redeploy alone restores lost data.',
        'Define the evidence required before removing the old column.'),
    review('CI/CD','Medium','ci-health-rollback','Gate a canary on useful health signals',
        'A CI/CD canary passes because its process responds to /health, but real API requests fail due to a missing permission. Design readiness, representative smoke checks, and an automated stop/rollback policy with thresholds and a bounded observation window.',
        'Measure serving correctness rather than mere process existence.',
        ['Use representative authorized request checks and relevant error/latency signals.','Specify stop conditions and verify rollback health rather than blindly looping deployments.'],
        [['Process alive but required dependency action denied','Canary fails readiness/smoke acceptance and promotion stops.'],['One expected transient warning occurs below policy thresholds','Do not rollback solely on an unclassified log line.']],
        ['Liveness, readiness, and end-to-end correctness answer different questions.','A canary needs enough representative traffic and an explicit baseline.'],
        'Before traffic promotion verify configuration and required least-privilege dependency access using safe probes. Observe canary error rates, latency, saturation, and selected business outcomes over a defined window versus baseline.\nOn a policy breach stop expansion and revert to a known-good compatible artifact/config pair, then verify recovery. Keep thresholds, minimum sample sizes, and manual escalation explicit; a quiet canary with no relevant traffic proves little. Avoid synthetic checks that mutate real user data without a controlled fixture contract.',
        'Define a low-traffic release strategy when statistical canary signals are insufficient.'),
    review('CI/CD','Hard','ci-untrusted-pr','Keep untrusted pull-request code away from deployment identity',
        'A CI/CD workflow grants a production token to a job that checks out and runs code from an external pull request. Design separate trust zones for contribution tests and protected promotion, including artifacts and caches that could carry attacker-controlled output.',
        'Treat build/test execution as code execution at its granted privilege level.',
        ['Run untrusted code with minimal token permissions and no production secrets.','Do not consume its artifacts/caches as trusted release inputs without a verified trusted rebuild/validation boundary.'],
        [['External PR modifies install/test scripts','Those scripts cannot access protected deployment credentials.'],['A privileged follow-up workflow downloads an untrusted artifact','It must not execute it as trusted deployment code.']],
        ['A workflow event name does not make checked-out code trusted.','Persistent runners and shared caches can bridge supposedly separate jobs.'],
        'Separate unprivileged contribution validation from protected builds/promotions of reviewed revisions. Restrict tokens, runner/network access, secret availability, and artifact/cache namespaces by trust level.\nUse short-lived environment-scoped deployment identity only after protected approvals and verify artifact provenance under the intended trust policy. Review dangerous checkout/event combinations and runner persistence. Test using dummy canaries rather than real credentials. Do not elevate a fork artifact solely because a previous workflow finished successfully.',
        'Specify a safe policy for self-hosted runners serving public contributions.'),
    review('CI/CD','Hard','ci-promotion-race','Prevent an older deployment from overwriting a newer release',
        'Two CI/CD runs deploy to the same environment. Newer release B finishes first, then slower release A overwrites it. Design environment serialization and expected-version promotion with a deliberate policy for rollbacks and operator overrides.',
        'Make environment state transitions ordered and auditable.',
        ['Use an environment deployment lock/concurrency policy and verify current desired revision.','Distinguish intentional rollback from accidental stale promotion.'],
        [['Old run A reaches promotion after B is current','Reject/supersede A unless explicitly approved as rollback.'],['Operator authorizes a compatible rollback','Record the intentional desired state and deploy it through the same controlled mechanism.']],
        ['Cancelling a runner may not cancel an already accepted external deploy.','The deployment system needs state checks as well as CI scheduling.'],
        'Serialize promotion per environment and store a generation/desired-artifact identity in the deployment control plane. Require a compare-and-set expected generation or equivalent stale-run rejection when applying changes.\nTreat rollback as a new audited desired-state operation, not a numeric version comparison hack. Ensure cancelled/superseded runs cannot keep mutating infrastructure after losing ownership; use fencing where needed. Test slow/fast overlapping runs, lost acknowledgements, and explicit overrides against the real deployment adapter in a safe environment.',
        'Define how a deploy lease expiry prevents a resumed old worker from applying changes.'),
    review('CI/CD','Hard','ci-recovery-drill','Prove a release recovery plan with a controlled drill',
        'A CI/CD runbook says rollback is one click, but nobody has restored an artifact, configuration, and data after a failed migration. Design a staging recovery drill measuring recovery time and data loss with explicit pass/fail evidence.',
        'Validate recovery capability rather than document confidence.',
        ['Use disposable representative data and simulate a defined failure.','Measure artifact/config restoration, data integrity, recovery time, and recoverable data point.'],
        [['Old artifact starts but schema/data is incompatible','The drill fails; process startup alone is not recovery.'],['Restored application passes owned read/write and integrity checks','Record measured RTO/RPO and remaining limitations.']],
        ['A backup file existing does not prove restore works.','Recovery includes credentials, migrations, routing, and downstream compatibility.'],
        'Prepare an isolated environment with a known dataset and restore points, execute a controlled bad release, and follow the actual runbook under timed observation. Restore/promote compatible artifacts and configuration and apply the tested data recovery/forward-fix policy.\nVerify representative operations, counts/invariants, access boundaries, and traffic routing. Record achieved recovery time/data point, manual dependencies, and corrective actions. Never rehearse destructive recovery on existing production user records without separate authorization and safeguards.',
        'Add a drill in which the primary artifact registry is unavailable.'),

    review('Cloud','Easy','cloud-workload-role','Grant an API access to one storage prefix',
        'A Cloud API needs to read objects under one application prefix, but its instance holds an administrator access key. Design workload identity and a least-privilege storage policy without embedding a static credential in source or an image.',
        'Scope runtime identity to required actions and resources.',
        ['Use the platform’s managed workload role/short-lived identity.','Allow only required read actions/prefixes and deny unrelated writes/admin actions.'],
        [['API reads an approved object','Policy permits the necessary action.'],['API tries to delete an object or read another tenant prefix','Identity/resource policy and application authorization prevent it.']],
        ['Cloud identity is not automatically per-user authorization.','Policy tests need both allowed and denied resource/action pairs.'],
        'Attach a dedicated workload identity and narrowly scoped storage permissions to the runtime. Keep long-lived keys out of source, image layers, logs, and general CI jobs.\nEnforce tenant/user access in the application and use narrowly scoped signed capabilities when appropriate. Test actual role permissions in an isolated account/project and monitor denied actions. Resource policy, encryption-key access, and network controls may also participate; administrator access is not a sound troubleshooting default.',
        'Specify how the application obtains a new short-lived credential without a restart.'),
    review('Cloud','Easy','cloud-storage-choice','Choose storage by access and durability needs',
        'A Cloud backend stores uploaded PDFs, transactional user progress, and disposable generated previews. Choose appropriate storage categories for each and explain why a single ephemeral instance disk is not a durable shared record system.',
        'Separate objects, structured state, and recomputable cache data.',
        ['Use private object storage for documents and a transactional store for progress.','Document retention, backups, and rebuild policy separately for each data class.'],
        [['API instance is replaced','Authoritative documents/progress remain recoverable under the storage policy.'],['Preview cache is lost','It can be rebuilt without inventing lost user records.']],
        ['Access patterns and consistency needs determine the store.','Managed storage still needs permissions, deletion, and recovery design.'],
        'Store document bytes privately in an object store with stable metadata references; store progress in an owner-scoped database with required integrity and recovery controls. Treat previews as bounded derived cache where regeneration is acceptable.\nDefine encryption/key access, versioning/retention, deletion propagation, and tested backup/restore for authoritative data. Do not confuse provider durability figures with application availability or recovery from an authorized accidental deletion. Ephemeral disk may hold temporary work, not the only user record.',
        'Trace deletion of a document through object storage, metadata, and derived previews.'),
    review('Cloud','Easy','cloud-budget','Estimate a monthly baseline before adding redundancy',
        'A Cloud design uses two instances priced at 0.10 currency units per hour each, plus 20 units of storage and 15 of estimated egress monthly. Estimate a 730-hour baseline and identify omitted cost categories rather than presenting it as a guaranteed bill.',
        'Calculate a transparent cost estimate with stated assumptions.',
        ['Compute 2*0.10*730+20+15=181 under the fixture assumptions.','List request, logging, backup, tax, and variable-transfer costs that may change the total.'],
        [['Fixture monthly assumptions hold','Baseline is 181 currency units.'],['Traffic or log retention doubles','Re-estimate variable categories; do not assume all costs scale identically.']],
        ['Separate fixed capacity from usage-sensitive charges.','A budget alert usually does not itself stop spending.'],
        'Compute instance cost as 146, then add storage 20 and egress 15 for a baseline of 181. Record region, currency, time window, and assumed usage; these fixture rates are not current provider prices.\nInclude load balancer, requests, managed database, observability, backups, cross-zone transfer, support, and other relevant costs before approval. Use cost allocation and alerts plus explicit quotas/admission where spend must be bounded. Validate estimates against real usage and reliability requirements.',
        'Define a unit-cost metric such as cost per successful document analysis.'),
    review('Cloud','Medium','cloud-zones','Survive one zone failure without forgetting dependencies',
        'A Cloud API has replicas in two availability zones but one database instance and one zone-bound dependency. Design a single-zone-failure acceptance test and identify which components must change before claiming the whole service is zone-resilient.',
        'Evaluate end-to-end failure domains rather than replica count alone.',
        ['Include database, ingress, queues, secrets, and capacity in the dependency map.','Define failover behavior, data consistency, and spare capacity under one-zone loss.'],
        [['One API zone becomes unavailable','Remaining healthy capacity can serve the required workload under policy.'],['Database in the failed zone has no supported failover','The overall service is not resilient merely because another API replica exists.']],
        ['A failure domain includes every required dependency.','Failover can trade availability, recovery time, and data-loss risk.'],
        'Map required components by zone and choose supported multi-zone/state failover mechanisms with measured RTO/RPO. Distribute stateless replicas and ingress while provisioning enough surviving capacity and testing health-routing changes.\nExercise a controlled zone dependency failure and verify reads, writes, reconnects, and data invariants. Account for regional services and correlated configuration faults. Do not claim zero data loss or instant recovery without verifying the database replication and failover contract under the chosen settings.',
        'Specify a degraded mode for optional dependencies during zone recovery.'),
    review('Cloud','Medium','cloud-private-download','Serve an authorized object with a bounded download capability',
        'A Cloud storage bucket becomes public to simplify user document downloads. Replace that design with private storage and short-lived scoped download authorization, considering leaked links, expiry, and object ownership checks.',
        'Separate object existence from permission to download it.',
        ['Authorize the requesting user against object metadata before issuing access.','Limit signed capability action, object, and lifetime and keep bucket public access disabled.'],
        [['User owns document d1','Issue only the intended short-lived read capability.'],['User guesses another account’s object key','Deny before issuing any capability.']],
        ['An unpredictable object key is not an access-control rule.','Anyone holding a bearer URL can use its grant until the provider/policy stops it.'],
        'Keep the bucket private and resolve an application document ID to an owner-scoped object record. After authorization issue a supported signed read URL with a short bounded lifetime, or proxy the download when stronger per-request revocation is required.\nAvoid logging capability URLs, use safe response/content disposition and referrer/cache policy, and consider that an existing URL may outlive a later permission change. Scope storage identity and encryption-key access narrowly. Test expiration, wrong object, wrong user, and leaked-link behavior under the documented contract.',
        'Compare signed URLs with an authenticated download proxy for immediately revocable documents.'),
    review('Cloud','Medium','cloud-autoscale','Autoscale using evidence without overwhelming the database',
        'A Cloud API scales from 2 to 20 replicas on CPU. Each opens 30 database connections, while the database budget is 200. Design scaling limits, pool sizing, and useful demand signals instead of increasing replicas without regard to downstream capacity.',
        'Treat scaling as a coordinated resource budget.',
        ['Account for 20*30=600 possible connections plus other clients.','Cap/resize pools and scaling against the actual database and workload budget.'],
        [['Twenty replicas retain pools of thirty','The theoretical demand exceeds the 200-connection fixture budget.'],['Requests queue on a slow external dependency with low CPU','CPU alone may fail to trigger the right overload response.']],
        ['Per-replica defaults multiply across the fleet.','Scaling signals should distinguish demand, saturation, and dependency latency.'],
        'Reserve headroom for administrative/other clients and choose a per-replica pool plus replica ceiling that respects the database budget; evaluate a supported connection proxy/pooler where appropriate. Scale from measured concurrency/queue/latency and CPU evidence.\nUse stabilization windows, readiness, graceful draining, and maximum spend/capacity bounds. Add backpressure for bottlenecked dependencies rather than scaling callers into a failing database. Load-test both scale-out and scale-in with the real pool lifecycle and verify connection totals.',
        'Define the scale-in policy for long-running requests.'),
    review('Cloud','Hard','cloud-disaster-recovery','Recover from a regional failure with verified data targets',
        'A Cloud service needs a four-hour recovery-time target and a fifteen-minute recovery-point target after regional loss. Design a recovery strategy and drill that includes database, objects, identity/configuration, DNS/routing, and dependency availability, without equating replicated corruption with a safe backup.',
        'Validate an end-to-end recovery path against explicit RTO/RPO.',
        ['Measure restore/failover time and the recoverable data boundary.','Include immutable recovery history and verification rather than relying only on live replication.'],
        [['A regional outage occurs','The tested plan restores required functions within the stated measured targets or reports a gap.'],['An accidental deletion replicates to the secondary','Recovery needs an appropriate retained restore point, not simply the latest replica.']],
        ['Replication can copy mistakes as well as valid changes.','Recovery depends on credentials, keys, artifacts, and external integrations too.'],
        'Choose backup/replication and warm/cold standby mechanisms consistent with the targets and budget. Preserve restore points and required encryption-key/identity access in the recovery environment; version artifacts/config and automate safe provisioning.\nRehearse in isolation with known data and timed steps, then verify referential/ownership invariants, objects, APIs, and traffic routing. Record achieved loss/time rather than planned values. Define split-brain prevention, return-to-primary, and authority to declare failover; do not promise a secondary region solves every correlated policy or credential fault.',
        'Specify evidence proving a restore has not reintroduced deleted private documents.'),
    review('Cloud','Hard','cloud-egress','Constrain a worker that processes untrusted URLs',
        'A Cloud worker downloads user-provided document URLs while holding storage permissions. Design an egress/identity boundary preventing private-network and metadata access, with bounded redirects, sizes, DNS behavior, and short-lived storage authority.',
        'Separate untrusted network input from cloud control-plane authority.',
        ['Prefer fixed provider/resource mappings and apply network-level egress restrictions.','Validate every destination/redirect and bound download and parsing work.'],
        [['URL resolves to metadata or private infrastructure','The fetch is blocked independently of browser CORS.'],['Public URL redirects to an internal address','The redirected hop is rejected under the same policy.']],
        ['The worker uses server network privileges, not the browser’s origin rules.','A one-time hostname check can lose to resolution/connect races.'],
        'Isolate fetching with a least-privilege workload role, approved egress paths, and no unnecessary control-plane reachability. Use vetted SSRF controls covering schemes, ports, IPv4/IPv6, DNS resolution at connection time, redirects, byte/time limits, and parser resource limits.\nWhere possible fetch through constrained provider IDs or an isolated fetch service and pass only approved bytes to privileged processing. Protect metadata access using platform mechanisms as defense in depth, not the sole URL validator. Test rebinding/redirect cases through controlled fixtures without targeting real internal services.',
        'Define the minimal object-store capability required for one accepted job.'),
    review('Cloud','Hard','cloud-noisy-neighbor','Bound tenant spend and shared-resource use',
        'A Cloud AI feature lets one tenant launch thousands of large jobs, consuming worker capacity and external API budget. Design tenant-aware admission, reservations, usage reconciliation, and alarms while explaining why a billing alert alone is not an enforcement mechanism.',
        'Coordinate capacity fairness with financial limits.',
        ['Enforce authenticated tenant budgets and active/queued work limits before admission.','Make reservation/usage updates idempotent and distinguish uncertain external charges.'],
        [['Tenant exhausts allowed spend or concurrency','Reject/defer within policy before unbounded expensive work starts.'],['Usage callback is delivered twice','The same operation is charged/accounted once under the reconciliation contract.']],
        ['Alarms notify after observations; admission controls decide whether work starts.','Resource and cost budgets have different units and time windows.'],
        'Define per-tenant and global limits for input size, active jobs, bounded queues, and estimated spend. Atomically reserve budget using a stable job/operation ID, execute only admitted work, and reconcile measured usage with replay-safe accounting.\nUse fair scheduling and alerts for unusual unit cost, lag, or exhausted budgets. Do not refund an uncertain external operation blindly or trust a client-supplied tenant ID. Test duplicate submissions, delayed usage, cancellation, and a noisy tenant alongside a small legitimate workload.',
        'Design an administrative budget increase with an auditable approval boundary.'),

    review('Caching','Easy','cache-aside','Trace a cache-aside read through a miss',
        'A Caching exercise uses cache-aside for public product descriptions. Describe hit and miss paths with a sixty-second TTL and identify the database as source of truth. A cache miss must not be treated as proof that the product does not exist.',
        'Separate cached availability from authoritative record existence.',
        ['On miss query the authoritative store and populate a bounded cache entry.','Do not invent a successful empty product when the database fails.'],
        [['Cache hit for a permitted product key','Return the cached public representation under its freshness contract.'],['Cache miss and database returns a valid product','Return it and populate with bounded TTL; database failure remains a failure.']],
        ['Cache-aside makes the application responsible for filling the cache.','A cache is normally an optimization, not proof that state is durable.'],
        'Validate the product ID, read its scoped/public cache key, and on miss load from the authoritative database. Cache only the intended public DTO with an explicit TTL, then return it.\nChoose a cache-outage bypass policy that the database can sustain; do not silently turn every error into a miss under unlimited load. Distinguish not-found, transient DB failure, and a valid empty field. Test expiry with an injected clock and bounded cache memory rather than waiting in real time.',
        'Define whether the API may serve a stale value during an authoritative outage.'),
    review('Caching','Easy','cache-key-scope','Include every response-shaping dimension in a private cache key',
        'A Caching API stores a private dashboard under dashboard:{path}. Different tenants receive each other’s data. Design a key and access flow accounting for verified tenant/user, representation version, and filters without placing bearer secrets in the key.',
        'Prevent cache-key aliasing across authorization and representation boundaries.',
        ['Authorize before exposing cached private data.','Include trusted scope and canonical response-shaping inputs, not raw credentials.'],
        [['Same path requested by users in two tenants','They cannot share private cached bodies accidentally.'],['Equivalent filter orders represent the same query','Canonical encoding can produce one stable safe key.']],
        ['A URL path may not capture who may see a response.','Ad hoc delimiter concatenation can create key collisions.'],
        'Derive verified scope and serialize a structured tuple such as [schemaVersion,tenantId,userId,resource,canonicalFilters,locale] through an unambiguous encoding/hash. Enforce current access policy even on a hit.\nDo not include raw tokens or assume key obscurity grants permission. Bound key cardinality, cache size, and TTL; document which representations are safe to share. Test tenant separation, locale/filter variants, and permission revocation. Shared public cache policy must be a deliberate distinct contract.',
        'Explain how a role-dependent response affects cache scope and invalidation.'),
    review('Caching','Easy','cache-ttl-boundary','Make TTL expiry deterministic at the boundary',
        'A Caching helper stores expiresAt in epoch milliseconds. Define a pure freshness check for an injected clock, requiring finite timestamps and considering the entry expired at now equal to expiresAt. Do not use truthiness to reject a cached value of zero.',
        'Separate cache value validity from time-based freshness.',
        ['Return false for absent or nonfinite timestamps.','Treat now >= expiresAt as expired while preserving legitimate falsy payloads.'],
        [['expiresAt=2000 and now=1999','Fresh under this arithmetic model.'],['expiresAt=2000 and now=2000, or entry is absent','Not fresh.']],
        ['Units must agree before comparing times.','The stored payload and the expiry metadata answer different questions.'],
        "const isFresh=(entry,now)=>Boolean(entry && Number.isFinite(now) && Number.isFinite(entry.expiresAt) && now < entry.expiresAt);\nValidate TTL configuration and compute bounded expiry at insertion using a consistent clock policy. A value of 0, false, or an empty list can be a valid cached result. This predicate is a deterministic time model, not a distributed clock guarantee or an authorization check; test clock anomalies and the actual store’s expiry behavior separately.",
        'Add a test for a malformed entry with expiresAt set to Infinity.'),
    review('Caching','Medium','cache-invalidation','Invalidate derived data after an authoritative update',
        'A Caching service updates a profile in the database but leaves its cached public DTO for ten minutes. Design a commit-then-invalidate workflow and explain the failure gap when invalidation fails after the write succeeds.',
        'Define a bounded freshness policy across database and cache operations.',
        ['Do not publish uncommitted state as authoritative cache content.','Bound stale reads and make failed invalidations observable/retryable.'],
        [['Database transaction rolls back','Do not populate the new profile as if it committed.'],['Write commits but invalidation fails','Record retryable invalidation and respect the documented staleness/recovery contract.']],
        ['Two independent systems do not share atomic commit by default.','A TTL is a fallback bound under assumptions, not immediate invalidation.'],
        'Commit the authoritative update first, then invalidate the relevant scoped keys; use a committed outbox/change event when invalidation intent must survive crashes. Retain a bounded TTL and monitor retry lag.\nDocument stale-read tolerance, or bypass/version-check cache for operations requiring current state. Avoid returning a failed-write message merely because optional cache invalidation failed after a successful mutation unless the API represents that partial result honestly. Test rollback, lost invalidation, and replay without deleting unrelated tenant keys.',
        'Describe how a profile update invalidates cached list and detail representations.'),
    review('Caching','Medium','cache-singleflight','Coalesce local concurrent cache misses without retaining failure forever',
        'A Caching process receives twenty requests for the same missing key. Design an in-flight promise map that shares one load, removes its entry on success or failure, and does not claim to coordinate independent API replicas.',
        'Deduplicate concurrent work within one process and recover after rejection.',
        ['Store a shared promise per key before exposing the asynchronous load.','Remove only the matching promise on settlement and keep value caching as a separate bounded policy.'],
        [['Two requests arrive before one load finishes','They share one operation and observe the same outcome.'],['Shared load fails, then a later request arrives','A new load may start; the rejected promise is not cached forever.']],
        ['Defer loader invocation through a promise so the map is set before it runs.','A finally-derived promise must itself be returned/observed.'],
        "function singleFlight(key,load,inflight){if(inflight.has(key))return inflight.get(key);let shared;shared=Promise.resolve().then(load).finally(()=>{if(inflight.get(key)===shared)inflight.delete(key);});inflight.set(key,shared);return shared;}\nBound distinct in-flight keys and underlying concurrency. This helper shares one process’s work only and does not provide cross-replica locking, persistent result TTL, or authorization. Caller cancellation must not automatically kill work still needed by other callers without an explicit ownership policy.",
        'Design a per-caller cancellation wrapper without cancelling the shared operation.'),
    review('Caching','Medium','cache-negative','Cache not-found results without hiding outages',
        'A Caching directory service receives repeated requests for missing public IDs. Propose short negative caching and distinguish an authoritative not-found from timeout, permission denial, and a newly created resource becoming visible.',
        'Reduce repeated misses without turning errors or private existence into cached facts.',
        ['Cache a typed not-found result only after the authoritative scoped query confirms it.','Use a short bounded TTL and invalidate/version on relevant creation.'],
        [['Authoritative query confirms absent public record','A brief typed negative entry can avoid repeated lookups.'],['Database times out','Do not cache the timeout as not-found.']],
        ['Absence is a result with a scope and freshness contract.','Permission-dependent absence must not leak through a shared unscoped key.'],
        'Represent negative entries distinctly from valid empty/zero data and transient failures. Key them by the required access scope, set a shorter TTL appropriate to creation frequency, and invalidate or version affected keys when records are created.\nDo not cache operational failures as absence or reuse one user’s denial for another user. Bound key/cardinality growth because arbitrary-ID requests can fill the cache. Test a missing ID, a transient outage, a later creation, and private-resource lookups with different actors.',
        'Specify a safe response during an outage when a negative entry is stale.'),
    review('Caching','Hard','cache-stampede','Prevent fleet-wide recomputation at a hot-key expiry',
        'A Caching fleet has fifty API replicas. A popular entry expires and every replica recomputes it, saturating the database. Design bounded regeneration, jitter, and stale-while-revalidate where stale data is permitted, including lock owner failure.',
        'Coordinate hot-key refresh without converting a cache miss into overload.',
        ['Bound refresh concurrency across replicas and add TTL jitter.','Use leased ownership/fencing or version-aware publication and a recovery policy for a dead refresher.'],
        [['Hot entry expires on many replicas','Only a bounded number of authoritative regenerations run.'],['Refresh owner dies or resumes after lease replacement','Others can recover; the stale owner cannot publish an obsolete result unconditionally.']],
        ['Local single-flight still permits one refresh per replica.','Serving stale data is appropriate only under an explicit freshness policy.'],
        'Combine local coalescing with a distributed lease/single-owner or other bounded refresh protocol. Add expiry jitter and, for permitted public/low-risk data, serve bounded stale content while one owner refreshes.\nUse tokens/version checks so late owners do not overwrite newer content, and cap waits/queueing when no stale value is allowed. A lease alone does not make cross-system publication atomic. Test owner crash, lease expiry, database slowdown, and a synchronized cold start, measuring downstream concurrency rather than only cache hit rate.',
        'Define an emergency bypass policy when the cache itself is unavailable.'),
    review('Caching','Hard','cache-stale-fill','Stop a late cache fill from undoing invalidation',
        'A Caching reader loads profile version 4, then a writer commits version 5 and invalidates the key. The delayed reader finally caches version 4. Explain why delete-after-write alone does not prevent this race and design version-aware publication.',
        'Protect freshness against in-flight readers across invalidation.',
        ['Carry an authoritative version and reject stale publication under a coordinated protocol.','State what information is retained after deletion to compare versions.'],
        [['Version 5 commits before delayed version 4 is published','The design must not blindly install version 4 as current.'],['Cache is empty after deletion','Absence alone does not prove the reader’s old version is safe.']],
        ['Invalidation cannot cancel every already-running read.','A version pointer/tombstone must survive long enough to fence stale fills.'],
        'Use immutable versioned cache entries with an authoritative/version-aware pointer, or a watermark/fencing protocol that refuses older publications. Ensure writer events advance the freshness authority rather than merely deleting all evidence.\nDefine ordering, retained watermarks, event replay, and behavior on authority unavailability. Alternative stronger read paths may bypass cache for critical state. Test delayed readers with barriers around commit/invalidate/fill. A second delayed delete can narrow a race but is not a universal proof against arbitrary delays.',
        'Specify how watermark expiry is chosen relative to maximum in-flight read lifetime.'),
    review('Caching','Hard','cache-security-state','Keep current authorization out of an unsafe stale cache',
        'A Caching optimization stores membership decisions for an hour and serves them during policy-service outages. An administrator is removed but retains a cached allow. Design risk-based freshness and fail-closed behavior for protected writes without treating all public reads identically.',
        'Make cached authority follow the required revocation contract.',
        ['Require a fresh/version-valid grant for sensitive operations.','Document any bounded stale-read policy and reject unknown authority rather than defaulting to allow.'],
        [['Membership removed before protected write admission','Old cached allow must not satisfy a policy requiring current membership.'],['Public product description cache is temporarily stale','It can follow a different explicit non-sensitive freshness policy.']],
        ['Cached content and cached permission are different risks.','Invalidation messages can be delayed or lost.'],
        'Classify data/actions by freshness risk. For sensitive writes verify current authority through an authoritative/versioned path and coordinate with the write if revocation races matter. Fail closed when mandatory permission state cannot be established.\nFor permitted low-risk reads document a bounded stale window, TTL, invalidation recovery, and monitoring. Key decisions by subject/tenant/action/resource/policy version and never leak one actor’s private cached result to another. Test missed invalidations, policy outage, and a membership change racing the protected effect.',
        'Define an emergency revocation mechanism that overrides cached decisions.'),

    review('Queues','Easy','queue-ack','Acknowledge work only after its required effect is confirmed',
        'A Queues worker acknowledges a job immediately on receipt, then writes its result. If it crashes during processing the broker considers the job complete. Define the acknowledgement boundary and explain why moving the ack does not remove duplicate-delivery risk.',
        'Separate receiving a message from durably completing its business effect.',
        ['Acknowledge only after the required durable outcome is confirmed.','Make redelivery safe through operation identity/idempotency.'],
        [['Worker crashes before the effect commits','Unacknowledged work can be redelivered under the broker contract.'],['Worker commits then crashes before ack','The job can repeat; processing must recognize the prior effect.']],
        ['At-least-once delivery is not exactly-once business execution.','The database effect and broker acknowledgement are usually separate boundaries.'],
        'Validate and authorize the job, execute the required durable effect with a stable operation ID, then acknowledge confirmed completion. If processing fails before completion, leave/retry according to the broker policy rather than falsely acking success.\nDeduplicate the effect atomically with application state, or use an idempotent destination API. A crash between commit and ack can redeliver a completed job. Test both crash positions and do not assume a message’s delivery identifier is stable across every broker retry.',
        'Specify how a permanently invalid job differs from a transient processing failure.'),
    review('Queues','Easy','queue-visibility','Align job duration with visibility and lease extension',
        'A Queues broker hides a received job for 30 seconds, but processing takes 90 seconds. A second worker receives it while the first still runs. Explain visibility timeout and design bounded lease extension plus idempotency without assuming a hidden message is permanently locked.',
        'Treat visibility as a time-bounded delivery lease.',
        ['Choose a measured timeout/heartbeat policy and cap total processing lifetime.','Handle duplicate concurrent processing even when lease renewal is attempted.'],
        [['Job exceeds visibility with no renewal','Another worker may receive it.'],['Worker dies while owning a lease','The message becomes eligible again after the applicable timeout.']],
        ['A lease expiring does not stop the old worker’s CPU or network calls.','Renewals can fail and are not an exactly-once guarantee.'],
        'Set initial visibility from measured work duration, renew while healthy within a bounded job deadline, and stop accepting new work during shutdown. Ack only after confirmed completion.\nUse stable idempotency keys/fencing at the effect boundary so a delayed or duplicate worker cannot create repeated side effects. Monitor renewal failures, age, and retries. Test a slow job, failed heartbeat, worker death, and an old worker resuming after another claim. Provider limits and lease semantics must be verified for the selected broker.',
        'Define the maximum total time a poison job may keep extending its lease.'),
    review('Queues','Easy','queue-contract','Version and validate a message before processing',
        'A Queues consumer expects {version:1,jobId,documentId,tenantId}, but producers sometimes omit identifiers or send a future version. Design envelope validation and trusted tenant authority before the worker accesses documents.',
        'Treat queue payloads as untrusted commands with explicit contracts.',
        ['Validate required types, supported version, and bounded payload size.','Authenticate/authorize producer and resource scope rather than trusting tenantId text alone.'],
        [['Valid supported command from an authorized producer','Process only the scoped accessible document.'],['Unsupported version or missing document ID','Reject/quarantine under policy instead of endlessly failing a null lookup.']],
        ['Durable transport does not prove semantic validity.','A version field allows intentional compatibility handling.'],
        'Validate a small versioned envelope with stable job/operation ID and bounded typed references. Verify the producer/workflow authority and constrain document access to the intended tenant and permitted action.\nQuarantine invalid/unsupported messages with safe metadata, preserve diagnostics without secret payload dumps, and avoid infinite retries for permanent schema errors. Test malformed envelopes, cross-tenant references, old/new supported versions, and duplicate jobs. Do not deserialize arbitrary executable object types from the message.',
        'Specify how a consumer upgrade supports one prior message version during rollout.'),
    review('Queues','Medium','queue-backoff','Retry transient failures with a bounded jittered schedule',
        'A Queues worker retries every failure immediately forever. A temporary downstream outage becomes a traffic storm while validation errors never resolve. Design classification, exponential backoff with jitter, attempt/deadline bounds, and a terminal outcome.',
        'Use retries as controlled recovery rather than unbounded repeated load.',
        ['Retry only documented transient/idempotent operations.','Bound attempts and elapsed time and route terminal failures to a reviewable state.'],
        [['Downstream returns a temporary availability error','Retry after bounded backoff according to the destination contract.'],['Message references an invalid unsupported type','Classify as permanent and quarantine instead of immediate retry.']],
        ['A timeout can have an uncertain effect outcome.','Jitter reduces synchronization but does not make unlimited retries safe.'],
        'Define retryable error classes and operation idempotency. Use capped exponential delay with jitter, respect supported Retry-After guidance, and stop at both attempt and elapsed-time budgets.\nKeep retry metadata stable through redelivery and send terminal failures to a DLQ/failed state with safe diagnostics. For uncertain side effects reconcile by operation ID rather than blindly starting a new effect. Limit aggregate retry traffic and test a sustained outage plus recovery to ensure retries do not overwhelm the dependency again.',
        'Define a maximum retry-to-original-traffic ratio during an outage.'),
    review('Queues','Medium','queue-dlq','Replay a dead-letter queue without repeating successful side effects',
        'A Queues job reaches a DLQ after repeated failures. Operators fix the parser and propose replaying every stored message automatically. Design inspection, scope, replay identity, and success verification without assuming every DLQ message is still valid or unprocessed.',
        'Make replay an explicit controlled business operation.',
        ['Inspect reason, age, schema, authority, and possible prior side effects.','Replay bounded approved subsets preserving logical operation identity and record the result.'],
        [['Parser bug is fixed for supported messages','Replay a measured authorized subset and verify outcomes.'],['Old message targets a deleted resource or already completed effect','Skip/reconcile under policy rather than recreating or duplicating it.']],
        ['A DLQ is a diagnostic queue, not permission to retry everything forever.','Retention and sensitive payload handling need an explicit policy.'],
        'Build a safe DLQ inspection workflow with redacted diagnostics and owner approval. Validate current message compatibility and authorization, reconcile uncertain effects, and replay a bounded batch with the same logical idempotency key.\nMonitor success/failure and pause on recurrent errors; record replay lineage separately from business operation identity. Keep originals/retention according to policy until recovery evidence is adequate. Test partial replay failure and interruption so a rerun does not duplicate completed effects.',
        'Specify how a replay tool prevents accidentally targeting production from a staging context.'),
    review('Queues','Medium','queue-backpressure','Bound prefetch when workers are slower than producers',
        'A Queues consumer fetches thousands of payloads into process memory while only four jobs can run. Design prefetch/admission and bounded local buffering so load remains in the broker rather than an unbounded worker heap.',
        'Coordinate broker delivery with actual processing capacity.',
        ['Bound active jobs and prefetched/in-memory payload bytes.','Monitor oldest-message age and arrival/service rates, not only queue length.'],
        [['Consumer concurrency is four','Prefetch follows a measured bounded allowance rather than fetching every available message.'],['Arrival rate exceeds service rate persistently','Backlog/age alarms and producer admission/scaling policy address the deficit.']],
        ['A broker can hold backlog more safely than a worker’s unbounded heap.','A short queue of very slow jobs may still violate latency goals.'],
        'Set broker prefetch/receive limits and a bounded local buffer consistent with concurrency, payload size, visibility, and memory budget. Fetch more only when capacity is available.\nMeasure arrival rate, completions, retries, oldest age, active jobs, and saturation. Scale within downstream limits or throttle/reject producers under policy; a finite queue/retention also needs an overflow plan. Test slow jobs and worker shutdown, and ensure queued-but-not-started leases do not expire unnoticed before work begins.',
        'Calculate a memory budget for four active and eight prefetched maximum-size messages.'),
    review('Queues','Hard','queue-inbox','Commit an inbox deduplication marker with the business effect',
        'A Queues consumer inserts a processed-message marker before updating a balance in a separate transaction. A crash after the marker causes redelivery to skip the missing balance change. Design an inbox transaction and distinguish local atomicity from remote side effects.',
        'Deduplicate a logical operation atomically with its durable local effect.',
        ['Use a unique stable operation key and commit marker plus balance change together.','Ack only after commit and define payload-conflict handling.'],
        [['Crash before the combined transaction commits','Neither marker nor balance effect is committed; redelivery can retry.'],['Commit succeeds but ack is lost','Redelivery recognizes the prior committed operation without another increment.']],
        ['A standalone marker can lose work or duplicate it depending on which side commits first.','Deduplication retention must cover the replay contract.'],
        'Within one database transaction claim a unique operation ID with an expected payload fingerprint, apply the authorized conditional balance change, and save the outcome/marker. On an exact duplicate return the stored outcome; reject mismatched reuse. Commit before acknowledging.\nKeep deduplication state for the required redelivery/replay window and enforce all monetary invariants. For a remote payment/email API, a local inbox cannot atomically include its effect; use destination idempotency or an explicit outbox/reconciliation design. Test concurrent duplicates and both crash windows.',
        'Define how a historical replay behaves after deduplication retention expires.'),
    review('Queues','Hard','queue-ordering','Preserve aggregate order without globally serializing all jobs',
        'A Queues system processes order updates version 2 and version 3 on different workers and applies version 2 last. Design per-order partitioning/serialization plus version checks, handling gaps and poison messages without pretending every queue guarantees global order.',
        'Enforce the ordering scope required by the business state.',
        ['Partition/group by aggregate identity and validate expected version.','Define gap/replay and poison-message behavior without blocking unrelated aggregates indefinitely.'],
        [['Order o1 receives version 3 before required version 2','Buffer/reconcile/reject under a bounded documented gap policy.'],['Order o1 is stuck but o2 has independent jobs','o2 can progress under the chosen partitioning/fairness design.']],
        ['The needed order is often per aggregate, not across all tenants.','Transport ordering does not replace application version/invariant checks.'],
        'Use a broker/worker routing contract that serializes a single aggregate’s stream or routes it to one owner. Include event/operation ID and aggregate version, and condition state transitions on expected version.\nFor gaps fetch/replay authoritative history or defer under a bounded policy; for duplicates return the saved outcome. Quarantine poison work with an explicit decision about later dependent events. Document broker ordering and redelivery limits, and test rebalance, worker death, duplicate versions, and out-of-order delivery. Avoid a global one-worker bottleneck unless the invariant genuinely requires it.',
        'Specify a safe partition-count change without reordering in-flight aggregate events.'),
    review('Queues','Hard','queue-outbox','Close the database-to-broker publication gap',
        'A Queues producer commits an order and then publishes a job. A crash between the two loses notification, while publishing first can expose an order that rolls back. Design a transactional outbox with bounded publisher claims and consumer idempotency.',
        'Persist message intent with the business record and deliver it separately.',
        ['Commit the order and unique outbox event in the same supported database transaction.','Expect publish/ack uncertainty and duplicate delivery; preserve stable event identity.'],
        [['Producer crashes after order/outbox commit','A later publisher can recover the pending event.'],['Publisher sends then crashes before marking delivered','Message may repeat; the consumer deduplicates its logical effect.']],
        ['A local transaction does not normally include an unrelated broker send.','A lease-based publisher still needs safe recovery from stale owners.'],
        'Insert business state and a versioned outbox record atomically, then publish committed pending records through bounded workers. Use claim leases/fencing, retries, oldest-age monitoring, and safe failure diagnostics.\nPreserve the event/operation ID through publication and consumer processing; acknowledge and mark delivery only according to the broker contract. A crash between send and delivery mark permits repeats, so do not advertise universal exactly-once effects. Test rollback, publisher death, duplicate sends, and broker outage with backlog recovery.',
        'Define how retention avoids deleting unpublished outbox rows.'),

    review('Scalability','Easy','scale-latency-stages','Locate the dominant measured latency stage',
        'A Scalability trace records 20 ms ingress wait, 30 ms API work, 400 ms database wait, and 50 ms response transfer. Calculate total and dominant stage, then choose the next measurement rather than immediately adding API replicas.',
        'Use a latency breakdown to target the actual bottleneck.',
        ['Calculate total 500 ms and identify database wait as 80 percent.','Correlate query/connection wait evidence before proposing a capacity change.'],
        [['Fixture stages sum without overlap','Total is 500 ms; database wait contributes 400 ms.'],['API CPU is low but database pool queue is large','More API replicas may add pressure instead of reducing the bottleneck.']],
        ['Measure queueing and service time separately.','One trace is evidence for investigation, not a population-wide percentile.'],
        'Sum the supplied sequential stages to 500 ms and compute 400/500=0.8. Inspect database query plans, pool waits, lock contention, and downstream saturation for representative requests.\nCompare baseline and loaded distributions with the same workload, tracking errors as well as latency. Optimize the evidenced cause and retest; do not assume a larger API fleet fixes slow storage or a blocked dependency. If stages overlap, use a proper trace critical path rather than blindly adding durations.',
        'Design a load experiment that separates connection-pool queueing from query execution.'),
    review('Scalability','Easy','scale-load-balance','Distinguish request distribution from equal work',
        'A Scalability design sends six sequential requests through round robin to three API replicas. Predict the ideal count distribution, then explain why equal request counts do not guarantee equal CPU load or latency when costs differ.',
        'Evaluate a load-balancing algorithm against workload cost.',
        ['State the ideal two-requests-per-replica fixture result.','Include readiness, connection reuse, and variable request cost in real-system interpretation.'],
        [['Three identical healthy replicas and six ideal round-robin requests','Two per replica under the fixture assumptions.'],['One request performs expensive computation','Equal counts can still produce uneven resource use and tail latency.']],
        ['The balancing unit may be a connection rather than an individual request.','Different algorithms need different observability and failure policies.'],
        'For the ideal sequential round-robin fixture assign requests 1/4 to A, 2/5 to B, and 3/6 to C. In production inspect whether the balancer distributes connections, streams, or requests and how health changes selection.\nMeasure active work, queueing, CPU, and latency by replica without private high-cardinality labels. Consider least-outstanding or other workload-aware choices only after evidence. Balancing does not create capacity in a shared saturated dependency or make a failed replica healthy.',
        'Explain why a long-lived connection can skew an otherwise fair round-robin configuration.'),
    review('Scalability','Easy','scale-stateless','Move required state out of one API process',
        'A Scalability API stores authenticated sessions and uploaded documents only in local process/instance state. A second replica cannot serve the same user. Identify authoritative state versus disposable cache and design explicit external storage boundaries.',
        'Make replica replacement compatible with required user state.',
        ['Use an appropriate shared session authority and durable scoped document store.','Keep in-process caches disposable and reconstructible.'],
        [['Request moves from replica A to B','B can access authorized authoritative state under the same contract.'],['Replica A is lost','Its disappearance does not erase the only copy of required user documents.']],
        ['Stateless replicas still depend on stateful services.','Sticky routing hides some state coupling but does not recover a failed instance.'],
        'Externalize sessions to a suitable protected shared authority and document bytes/metadata to durable stores with ownership enforcement. Keep bounded local caches as optimizations with explicit expiry and miss behavior.\nDefine database/object recovery and dependency availability rather than claiming the whole system is stateless. Test cross-replica requests, restart, session revocation, and store outage. Do not make private storage public or put all state into a bearer token merely to avoid shared authority.',
        'Specify which temporary files may safely disappear during instance replacement.'),
    review('Scalability','Medium','scale-capacity','Use throughput and latency to estimate in-flight work',
        'A Scalability system is stable at 200 requests per second with mean time in system 0.25 seconds. Estimate mean in-flight work and explain why multiplying p99 latency by arrival rate does not give the same queueing result or a safe maximum pool size.',
        'Apply mean queueing relationships only under their assumptions.',
        ['Calculate mean concurrency 200*0.25=50 under stable steady-state assumptions.','Measure variance, bursts, and downstream limits before selecting a hard capacity bound.'],
        [['Stable fixture with matching throughput/time boundaries','Mean in-flight work is about 50.'],['Arrival rate exceeds sustainable completions','Queue grows and the stable-state interpretation no longer predicts a bounded backlog.']],
        ['Little’s law relates averages over a consistent system boundary.','Averages alone do not specify tail latency or burst tolerance.'],
        "const meanInflight=(ratePerSecond,meanSeconds)=>{if(!Number.isFinite(ratePerSecond)||!Number.isFinite(meanSeconds)||ratePerSecond<0||meanSeconds<0)throw new RangeError('Invalid measured means');return ratePerSecond*meanSeconds;};\nFor the stable fixture the estimate is 50. Use matching measurement boundaries and representative steady intervals; do not substitute p99 for mean latency or treat the output as an automatic pool limit. Load-test bursts, service-time variability, rejection policy, and downstream capacity before choosing admission bounds.",
        'Define separate measurements for active service time and time queued.'),
    review('Scalability','Medium','scale-pool-budget','Budget connections across the full replica fleet',
        'A Scalability rollout increases API replicas to twelve. Each pool may open twenty connections, while the database allows 200 and other clients reserve 40. Calculate the potential demand and design a fleet-safe ceiling with headroom.',
        'Account for per-instance resources multiplying under scale-out.',
        ['Recognize 240 API connections exceeds the 160 remaining fixture allowance.','Reserve operational headroom and coordinate pool size with maximum replicas.'],
        [['Twelve pools each reach twenty','Potential API demand is 240, not twenty.'],['Pool size is reduced to fit a maximum replica budget','Retest queueing/latency rather than assuming smaller pools are free.']],
        ['Idle, active, and maximum pool connections are different metrics.','A connection proxy may help but has its own semantics and capacity.'],
        'Start with total DB capacity minus known clients and safety headroom, then divide the allowed API allocation across the maximum fleet. For the fixture, 12*20=240 exceeds 200-40=160 even before extra headroom.\nChoose a lower per-replica cap and/or replica ceiling, evaluate a supported pooler, and add bounded request admission. Test rollout overlap, failover, scale-in, and leaks because old/new replicas may temporarily coexist. Monitor waiting requests and query latency instead of only successful connection counts.',
        'Include a rolling deployment surge allowance in the budget.'),
    review('Scalability','Medium','scale-observability','Define SLO-oriented measurements for a scaling experiment',
        'A Scalability team declares success because average latency improved after adding replicas, but timeouts and p99 latency worsened. Design a comparison including error rate, percentiles, throughput, saturation, and workload consistency.',
        'Evaluate serving quality and resource pressure together.',
        ['Count unsuccessful/timed-out requests rather than excluding them from the report.','Use comparable workload and SLO windows and investigate per-dependency saturation.'],
        [['Only fast successful requests enter the average','The result can conceal severe failure and is insufficient.'],['Loaded test shows higher goodput but unacceptable timeout fraction','The release fails the stated reliability target.']],
        ['Throughput includes attempted work; useful successful throughput is a separate outcome.','Tail observations need adequate sample sizes and consistent definitions.'],
        'Define availability and latency SLOs, count all attempted outcomes with explicit timeout treatment, and compare goodput/error rate plus p50/p95/p99 under the same request mix and arrival pattern.\nCapture CPU, memory, event-loop delay, pool wait, queue age, dependency latency, and resource cost. Use traces/logs with bounded labels and privacy controls to isolate regressions. Report confidence/sample limitations and test recovery after overload. An average-only dashboard cannot establish improved user experience.',
        'Specify a rollback threshold that combines error budget burn and latency regression.'),
    review('Scalability','Hard','scale-overload','Stop a dependency slowdown from cascading through retries',
        'A Scalability incident begins with a slow database. API queues grow, clients timeout and retry, and connection pools exhaust. Design a layered overload policy with deadlines, bounded work, shedding, and retry budgets that does not retry every request at every hop.',
        'Keep admitted demand within sustainable capacity during partial failure.',
        ['Bound concurrency and queues and propagate an overall deadline.','Retry only suitable idempotent operations with a single coordinated budget and jitter.'],
        [['Database slows beyond the request deadline','Cancel/cooperatively stop owned work where supported and shed excess demand.'],['Several layers each retry three times','Replace multiplicative retry amplification with an explicit end-to-end policy.']],
        ['More callers can make a saturated dependency less available.','Circuit breakers and timeouts need measured thresholds and recovery probes.'],
        'Limit admitted in-flight work and queue wait against downstream budgets, propagate remaining deadlines, and return controlled overload responses before retaining unbounded requests. Use breakers or adaptive limits with bounded recovery probes where justified.\nAssign retry ownership and a capped budget, respect idempotency/uncertain outcome rules, and add jitter. Observe shed work, retries, saturation, and recovery rather than only accepted throughput. Test a slow dependency, partial recovery, and a retrying client population; do not claim cancellation rolls back an already committed effect.',
        'Define the client contract distinguishing retryable overload from permanent invalid input.'),
    review('Scalability','Hard','scale-shard-hotkey','Evaluate sharding against tenant skew and query requirements',
        'A Scalability database has one tenant generating half of all traffic. Hashing solely by tenantId preserves tenant locality but puts that tenant on one shard. Design a measured partition strategy considering hot keys, cross-partition queries, rebalancing, and integrity boundaries.',
        'Choose partition keys from workload distribution and access invariants.',
        ['Measure key skew and dominant read/write paths before choosing partitions.','State routing, migration, and cross-partition consistency costs.'],
        [['One tenant dominates writes','Tenant-only partitioning may retain the hotspot.'],['The tenant is split by another key','Some tenant-wide queries/transactions now span partitions and need an explicit strategy.']],
        ['Even shard counts do not imply even work.','A partition key is also a query-routing and data-migration contract.'],
        'Measure tenant/resource skew, write rates, storage growth, and query shapes. Compare tenant-local placement with subpartitioning dominant tenants by a stable entity/time/bucket key, documenting scatter-gather and transaction limits.\nDesign versioned routing, online migration with checkpoints/verification, and safe cutover under concurrent writes. Address global uniqueness, foreign relationships, backups, and rebalance failure. Test the hottest realistic key and tenant-wide reports; adding shards without changing a single hot aggregate may not distribute its serialized work.',
        'Specify how a routing version prevents stale clients from writing to the old partition after cutover.'),
    review('Scalability','Hard','scale-multiregion','Choose multi-region behavior around a write invariant',
        'A Scalability proposal enables active-active writes in two regions to improve latency. The product sells the last seat in a course and must not oversell. Compare single-writer routing, consensus-backed coordination, and asynchronous conflict resolution under a regional partition.',
        'State latency, availability, and invariant trade-offs under partitions.',
        ['Prevent independent regions from both spending the same remaining capacity without a coordination/allocation protocol.','Define failover authority, fencing, and recovery behavior.'],
        [['Network partition leaves each region seeing one remaining seat','Independent unchecked acceptance can oversell.'],['One region is the authoritative writer and is unreachable','Choose a documented unavailable/degraded or safely fenced failover behavior rather than accepting conflicting writes blindly.']],
        ['Replicated reads and independent writes have different consistency risks.','Conflict reconciliation after sale may be unacceptable for the invariant.'],
        'Choose a supported strong coordination mechanism, single-writer/fenced failover design, or carefully allocated regional inventory that preserves the capacity invariant. Measure the resulting latency and availability and explicitly reject/defer work when required authority is unavailable.\nDo not promise simultaneous low-latency independent writes and strict shared-seat enforcement during arbitrary partitions. Define data replication lag, writer fencing, reconnection reconciliation, and client routing; test a partition and stale writer return, not just a clean regional restart.',
        'Design a regional capacity allocation policy and explain how unused allocation is transferred safely.')
];
